CREATE TRIGGER trg_bills_relationship_guard
BEFORE INSERT ON bills
FOR EACH ROW
BEGIN
    DECLARE occupancy_resident BIGINT UNSIGNED DEFAULT NULL;
    DECLARE occupancy_room BIGINT UNSIGNED DEFAULT NULL;
    DECLARE occupancy_rent DECIMAL(12,2) DEFAULT NULL;
    DECLARE occupancy_move_in DATE DEFAULT NULL;
    DECLARE occupancy_move_out DATE DEFAULT NULL;
    DECLARE occupancy_opening_water DECIMAL(14,2) DEFAULT NULL;
    DECLARE occupancy_opening_electric DECIMAL(14,2) DEFAULT NULL;
    DECLARE water_previous DECIMAL(14,2) DEFAULT NULL;
    DECLARE water_current DECIMAL(14,2) DEFAULT NULL;
    DECLARE water_units DECIMAL(14,2) DEFAULT NULL;
    DECLARE electric_previous DECIMAL(14,2) DEFAULT NULL;
    DECLARE electric_current DECIMAL(14,2) DEFAULT NULL;
    DECLARE electric_units DECIMAL(14,2) DEFAULT NULL;

    SELECT resident_id, room_id, monthly_rent, move_in_date, move_out_date,
           opening_water_reading, opening_electric_reading
      INTO occupancy_resident, occupancy_room, occupancy_rent,
           occupancy_move_in, occupancy_move_out,
           occupancy_opening_water, occupancy_opening_electric
      FROM occupancies
     WHERE id = NEW.occupancy_id
     LIMIT 1
     FOR SHARE;
    IF occupancy_opening_water IS NULL OR occupancy_opening_electric IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Complete both occupancy opening readings before issuing bills';
    END IF;
    SELECT previous_reading, current_reading, units_used
      INTO water_previous, water_current, water_units
      FROM meter_readings
     WHERE room_id = NEW.room_id
       AND occupancy_id = NEW.occupancy_id
       AND meter_type = 'water'
       AND period = NEW.period
     LIMIT 1
     FOR SHARE;
    SELECT previous_reading, current_reading, units_used
      INTO electric_previous, electric_current, electric_units
      FROM meter_readings
     WHERE room_id = NEW.room_id
       AND occupancy_id = NEW.occupancy_id
       AND meter_type = 'electric'
       AND period = NEW.period
     LIMIT 1
     FOR SHARE;

    IF NEW.status <> 'pending'
        OR NEW.paid_at IS NOT NULL
        OR NOT (occupancy_resident <=> NEW.resident_id)
        OR NOT (occupancy_room <=> NEW.room_id) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Bill must start pending and match its occupancy';
    END IF;
    IF NOT (occupancy_rent <=> NEW.rent_amount)
        OR NEW.period < DATE_FORMAT(occupancy_move_in, '%Y-%m-01')
        OR NEW.period > DATE_FORMAT(COALESCE(occupancy_move_out, '9999-12-31'), '%Y-%m-01')
        OR NOT (water_previous <=> NEW.water_previous)
        OR NOT (water_current <=> NEW.water_current)
        OR NOT (water_units <=> NEW.water_units)
        OR NOT (electric_previous <=> NEW.electric_previous)
        OR NOT (electric_current <=> NEW.electric_current)
        OR NOT (electric_units <=> NEW.electric_units) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Bill rent and meter snapshots must match its occupancy period';
    END IF;
END$$

CREATE TRIGGER trg_bills_no_delete
BEFORE DELETE ON bills
FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Issued bills cannot be deleted';
END$$

-- expected_other_description is compared with bill_items.description using <=>.
-- Both operands are IMPLICIT, so different collations raise error 1267 and every
-- bill item insert fails. The database is utf8mb4_unicode_ci only when created by
-- database/install.sql; a managed host or MYSQL_DATABASE gives it the server
-- default, so the declaration pins the collation rather than inheriting it.
CREATE TRIGGER trg_bill_items_insert_guard
BEFORE INSERT ON bill_items
FOR EACH ROW
BEGIN
    DECLARE expected_quantity DECIMAL(14,2) DEFAULT NULL;
    DECLARE expected_unit_price DECIMAL(14,2) DEFAULT NULL;
    DECLARE expected_amount DECIMAL(14,2) DEFAULT NULL;
    DECLARE expected_other_description VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL;

    SELECT CASE NEW.item_type
               WHEN 'rent' THEN 1.00
               WHEN 'water' THEN water_units
               WHEN 'electric' THEN electric_units
               WHEN 'other' THEN 1.00
           END,
           CASE NEW.item_type
               WHEN 'rent' THEN rent_amount
               WHEN 'water' THEN water_rate
               WHEN 'electric' THEN electric_rate
               WHEN 'other' THEN other_amount
           END,
           CASE NEW.item_type
               WHEN 'rent' THEN rent_amount
               WHEN 'water' THEN water_amount
               WHEN 'electric' THEN electric_amount
               WHEN 'other' THEN other_amount
           END,
           other_description
      INTO expected_quantity, expected_unit_price, expected_amount, expected_other_description
      FROM bills
     WHERE id = NEW.bill_id
     LIMIT 1;

    IF NOT (expected_quantity <=> NEW.quantity)
        OR NOT (expected_unit_price <=> NEW.unit_price)
        OR NOT (expected_amount <=> NEW.amount)
        OR (NEW.item_type = 'other'
            AND (expected_amount <= 0 OR NOT (expected_other_description <=> NEW.description))) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Bill item must match its issued bill snapshot';
    END IF;
END$$

CREATE TRIGGER trg_bill_items_no_update
BEFORE UPDATE ON bill_items
FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Bill items are immutable';
END$$

CREATE TRIGGER trg_bill_items_no_delete
BEFORE DELETE ON bill_items
FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Bill items are immutable';
END$$

-- The string local pins its collation for the same reason as the guards above.
CREATE TRIGGER trg_payments_relationship_guard
BEFORE INSERT ON payments
FOR EACH ROW
BEGIN
    DECLARE bill_resident BIGINT UNSIGNED DEFAULT NULL;
    DECLARE bill_total DECIMAL(14,2) DEFAULT NULL;
    DECLARE bill_status VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL;
    SELECT resident_id, total_amount, status
      INTO bill_resident, bill_total, bill_status
      FROM bills
     WHERE id = NEW.bill_id
     LIMIT 1;
    IF NOT (bill_resident <=> NEW.resident_id)
        OR NOT (bill_total <=> NEW.amount)
        OR bill_status <> 'pending'
        OR NEW.status <> 'pending' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Payment must start pending and match a pending bill';
    END IF;
END$$

CREATE TRIGGER trg_payments_final_immutable
BEFORE UPDATE ON payments
FOR EACH ROW
BEGIN
    IF NOT (OLD.bill_id <=> NEW.bill_id)
        OR NOT (OLD.resident_id <=> NEW.resident_id)
        OR NOT (OLD.amount <=> NEW.amount)
        OR NOT (OLD.slip_path <=> NEW.slip_path)
